import streamlit as st
import joblib
import pandas as pd
from pathlib import Path

st.set_page_config(page_title="Diabetes Risk Screening", page_icon="🩺", layout="centered")

MODEL_PATH = Path(__file__).parent / "diabetes_model.joblib"

st.title("Diabetes Risk Screening")
st.write(
    "Enter the health measurements below to view the model's estimated "
    "diabetes risk category."
)

if not MODEL_PATH.exists():
    st.error(
        "The trained model file (diabetes_model.joblib) is missing. "
        "Run the export cell in the notebook and place the generated file "
        "in the same GitHub folder as app.py."
    )
    st.stop()

artifact = joblib.load(MODEL_PATH)
model = artifact["model"]
threshold = float(artifact["threshold"])
feature_names = artifact["feature_names"]

st.caption("Educational research prototype only — not a medical diagnosis.")

# The Pima dataset uses these measurements. Inputs are matched to the
# feature order stored with the trained pipeline.
defaults = {
    "Pregnancies": 1.0,
    "Glucose": 120.0,
    "BloodPressure": 70.0,
    "SkinThickness": 20.0,
    "Insulin": 80.0,
    "BMI": 25.0,
    "DiabetesPedigreeFunction": 0.5,
    "Age": 30.0,
}
labels = {
    "Pregnancies": "Pregnancies",
    "Glucose": "Glucose (mg/dL)",
    "BloodPressure": "Blood pressure (mmHg)",
    "SkinThickness": "Skin thickness (mm)",
    "Insulin": "Insulin (mu U/mL)",
    "BMI": "BMI",
    "DiabetesPedigreeFunction": "Diabetes pedigree function",
    "Age": "Age (years)",
}

with st.form("prediction_form"):
    values = {}
    cols = st.columns(2)
    for idx, feature in enumerate(feature_names):
        with cols[idx % 2]:
            values[feature] = st.number_input(
                labels.get(feature, feature),
                min_value=0.0,
                value=float(defaults.get(feature, 0.0)),
                step=1.0 if feature in ("Pregnancies", "Age") else 0.1,
            )
    submitted = st.form_submit_button("Estimate risk", type="primary")

if submitted:
    input_df = pd.DataFrame([[values[f] for f in feature_names]], columns=feature_names)
    probability = float(model.predict_proba(input_df)[0][1])
    prediction = int(probability >= threshold)

    st.subheader("Model result")
    st.metric("Estimated probability for the positive class", f"{probability:.1%}")
    if prediction == 1:
        st.warning("The model classified this input as higher predicted risk.")
    else:
        st.success("The model classified this input as lower predicted risk.")

    st.caption(f"Classification threshold used: {threshold:.2f}")
    st.info(
        "This result is generated by a machine-learning model trained on a "
        "specific dataset. It cannot confirm or rule out diabetes. Please "
        "consult a qualified healthcare professional for testing and advice."
    )
